//! Regenerates the deterministic publication operation-report, evidence,
//! external-link slot, and package-identity goldens under
//! `examples/expected/`.
//!
//! Run with `cargo run --locked --bin generate-publication-goldens` after
//! any change to the publication report, evidence, external-link slot, or
//! package-identity renderers. The tracked-page golden
//! (`examples/expected/trace-page.md`) is a real `buoy trace --format
//! markdown` CLI capture and is not regenerated by this tool; see
//! `tests/usage_examples.rs`.

#![allow(clippy::expect_used)]

fn main() {
    let rendered_slot = buoy::external_link_generation::render_slot(
        "consumer-example-link",
        "EXAMPLE-001",
        "blake3-256:a352b07c143fff7a0aa8e2a57d65fba2ee2d59635fdb20191f68fe93ef21c87f",
        "documents",
        "https://example.invalid/trace/blake3-256/29fce2a3aa4972e09809482995a4f33636a11c2cac45ea87192bf9d49d7e01a5.md",
    );
    std::fs::write(
        "examples/expected/publication-external-link-slot.md",
        rendered_slot,
    )
    .expect("write external-link slot golden");

    let report = buoy::publication::PublicationReport::new("check", "trace-page");
    std::fs::write(
        "examples/expected/publication-operation-report.json",
        buoy::publication::render_report(&report).expect("report"),
    )
    .expect("write report golden");

    let evidence = buoy::publication::PublicationEvidence::new("consumer-example");
    std::fs::write(
        "examples/expected/publication-evidence.json",
        buoy::publication::render_evidence(&evidence),
    )
    .expect("write evidence golden");

    let identity = buoy::publication::PackageIdentity::new(
        "0.2.0",
        "0000000000000000000000000000000000000000",
        "nightly-2026-04-16",
        vec!["xxh3-128"],
    );
    std::fs::write(
        "examples/expected/package-identity.json",
        identity.render().expect("identity"),
    )
    .expect("write package identity golden");

    println!("publication-goldens: wrote 4 golden files under examples/expected/");
}
